module.exports = {
  onConnect: function(transport, config) {
    console.log('Connected to Studio Hub at ' + config.host);
    engine.setVariable('studio_online', 'true');
  },
  onMessage: function(transport, msg) {
    try {
      var data = JSON.parse(msg);
      if (data.active_scene) engine.setVariable('current_scene', data.active_scene);
      if (data.recording !== undefined) engine.setVariable('is_recording', String(data.recording));
    } catch (e) {}
  },
  onAction: function(transport, actionId, params) {
    transport.sendJSON({ action: actionId, params: params });
    return 'Action sent: ' + actionId;
  },
  onDisconnect: function() {
    engine.setVariable('studio_online', 'false');
  }
};
